const e={brief:"Design a global CDN that serves static and cacheable dynamic content with low latency, respects cache and authorization semantics, supports edge computation, and shields origins from traffic spikes and attacks.",successSignals:["Define origin authority, cache keys, TTL, validators, purge, stale serving, signed requests, and personalized-content boundaries.","Use regional shields, tiered caches, request coalescing, compression, and origin failover while avoiding cache poisoning.","Keep immutable assets aggressively cacheable and invalidate mutable content by version or tag rather than global flushes.","Explain DDoS/WAF controls, TLS, geo routing, private content, stale-if-error, observability, and purge correctness."]},t={functional:["Publish assets and cache policies, route requests to the nearest healthy edge, fetch from shield or origin on misses, and purge versions.","Support static assets, API caching, signed URLs, geographic variants, edge redirects, compression, and conditional requests.","Expose hit ratio, origin latency, stale serves, purge status, cache-key cardinality, attack traffic, and regional health."],nonFunctional:["Target cache hit ratio above 80% and p95 edge response below 100 ms for cacheable content.","Serve global traffic through distributed edges while isolating hot objects, high-cardinality keys, and abusive clients.","Make configuration publication and purge operations versioned and retry-safe; never expose private content through a shared key.","Serve stale safe content or fail over to a secondary origin when an origin or purge service is degraded."],scaleAssumptions:["Serve 10 million requests per second across 200 edge locations with large launch-time traffic spikes.","Partition cache and shield state by distribution, region, host, and normalized cache key; isolate hot objects.","Keep edge state bounded with TTL and eviction while retaining configuration, purge, security, and origin audit logs."],metrics:[{label:"Peak scale",value:"Monitor cache performance",description:"Capacity assumption that drives partitioning and backpressure."},{label:"Latency target",value:"Cache hit ratio above 80%",description:"User-facing budget for the primary request or read path."},{label:"Durable boundary",value:"Committed before async",description:"The source of truth is Serve static and dynamic content globally; Minimize latency for users worldwide."},{label:"Async boundary",value:"At-least-once workers",description:"Keep CloudFront for CDN, S3 as origin for static content, Lambda@Edge for edge computing off the synchronous path."}]},o=[{name:"MediaAsset",fields:["assetId","ownerId","sourceUri","checksum","privacy","status"],notes:"Canonical uploaded global content delivery network asset and lifecycle state."},{name:"MediaRendition",fields:["assetId","profile","codec","uri","checksum","status"],notes:"Derived global content delivery network output identified by a deterministic profile and content hash."},{name:"PlaybackSession",fields:["sessionId","assetId","viewerId","entitlementVersion","edgeRegion","expiresAt"],notes:"Short-lived global content delivery network access session that binds authorization to delivery."},{name:"ProcessingJob",fields:["jobId","assetId","operation","attempt","checkpoint","status"],notes:"Retry-safe global content delivery network processing job with checkpoints and per-rendition progress."}],a=[{method:"POST",path:"/v1/assets/uploads",contract:"{ contentType, size, checksum } -> { assetId, uploadUrl }",notes:"Issue a scoped global content delivery network upload URL and register the source before transfer."},{method:"POST",path:"/v1/assets/{assetId}/process",contract:"{ profiles[], priority, idempotencyKey } -> { jobId, status }",notes:"Start idempotent global content delivery network processing for requested output profiles."},{method:"GET",path:"/v1/assets/{assetId}/manifest",contract:"{ renditions[], policy, freshness }",notes:"Return available global content delivery network renditions only after entitlement and integrity checks."},{method:"POST",path:"/v1/playback-sessions",contract:"{ assetId, viewerId, device, entitlement } -> { sessionId, manifestUrl, expiresAt }",notes:"Create a short-lived authorized global content delivery network delivery session."}],i=[{title:"Reserve a resumable upload",description:"The global content delivery network gateway authenticates the owner, reserves metadata, validates size and checksum, and returns a scoped upload URL."},{title:"Commit and verify the source",description:"A completion callback verifies the global content delivery network object, records an immutable checksum, and publishes a processing job only once."},{title:"Process renditions asynchronously",description:"Workers execute global content delivery network transforms with deterministic profiles, checkpointing, bounded retries, and a dead-letter path for corrupt inputs."},{title:"Publish an entitlement-aware manifest",description:"A manifest projection exposes only completed global content delivery network renditions and carries policy, checksum, and freshness metadata."},{title:"Deliver, invalidate, and recover",description:"CDN delivery is protected by expiring URLs and revocation signals; failed global content delivery network jobs and stale manifests are replayable without duplicating outputs."}],n={title:"Global Content Delivery Network media architecture",summary:"Design a global CDN that serves static and cacheable dynamic content with low latency, respects cache and authorization semantics, supports edge computation, and shields origins from traffic spikes and attacks. The design keeps originals durable and private, turns processing into idempotent queue work, publishes only verified renditions, and serves playback through entitlement-scoped CDN manifests.",layers:[{id:"experience",label:"Media client and access plane",description:"Upload, status, metadata, entitlement, and playback requests are authenticated and quota-protected.",componentIds:["client","upload"]},{id:"source",label:"Original media and metadata plane",description:"Original bytes and ownership state remain durable sources for replay, processing, and deletion.",componentIds:["object-store","metadata"]},{id:"processing",label:"Media processing plane",description:"Durable prioritized jobs produce verified renditions and manifests asynchronously.",componentIds:["queue","processor","catalog"]},{id:"delivery",label:"Playback and download plane",description:"The CDN serves signed segments and downloads from complete, policy-approved renditions.",componentIds:["cdn"]},{id:"operations",label:"Media lifecycle operations",description:"Pipeline, delivery, abuse, storage, and deletion correctness are observable.",componentIds:["monitoring"]}],keyPaths:[{id:"upload",label:"Upload and processing path",description:"Client -> gateway -> object store and metadata -> processing queue -> rendition catalog.",componentIds:["client","upload","object-store","metadata","queue","processor","catalog"]},{id:"playback",label:"Playback path",description:"Client -> gateway -> entitlement -> rendition catalog -> signed CDN manifest -> client.",componentIds:["client","upload","metadata","catalog","cdn"]}],components:[{id:"client",type:"client",componentId:"web-app",label:"Media upload and playback clients",description:"Users upload media, inspect processing status, browse metadata, and request adaptive playback or downloads.",position:{x:0,y:240},properties:{protocol:"HTTPS upload, signed URLs, and adaptive streaming"}},{id:"upload",type:"api-gateway",componentId:"api-gateway",label:"Upload and playback gateway",description:"Authenticates users, issues scoped upload/download URLs, validates metadata, and protects playback and upload quotas.",position:{x:420,y:240},properties:{protection:"Auth, signed URLs, quotas, and abuse controls"}},{id:"object-store",type:"file-storage",componentId:"object-storage",label:"Original media object store",description:"Stores immutable originals and intermediate assets with checksum, encryption, lifecycle, and tenant ownership metadata.",position:{x:840,y:-80},properties:{storage:"Content-addressed objects and lifecycle tiers"}},{id:"metadata",type:"database",componentId:"database",label:"Media metadata and entitlement store",description:"Stores ownership, privacy, captions, renditions, processing state, playback policy, and deletion tombstones.",position:{x:840,y:520},properties:{consistency:"Versioned metadata and entitlement checks"}},{id:"queue",type:"queue",componentId:"queue",label:"Media processing queue",description:"Buffers thumbnail, waveform, caption, transcode, moderation, and packaging work with priority and retry isolation.",position:{x:1260,y:520},properties:{delivery:"Durable jobs, visibility timeout, and dead-letter handling"}},{id:"processor",type:"microservice",componentId:"processing-worker",label:"Transcoding and media processing",description:"Generates codec/bitrate renditions, thumbnails, captions, and manifests while reporting progress and content safety results.",position:{x:1680,y:520},properties:{scaling:"CPU/GPU pools partitioned by media size and priority"}},{id:"catalog",type:"database",componentId:"database",label:"Rendition and playback catalog",description:"Records available renditions, codecs, bitrates, segment manifests, captions, checksums, and processing versions.",position:{x:1680,y:240},properties:{consistency:"Publish only complete, checksum-verified renditions"}},{id:"cdn",type:"cdn",componentId:"cdn",label:"Playback and download CDN",description:"Serves signed, cacheable media segments and downloads from the rendition catalog while enforcing entitlement and expiry.",position:{x:2100,y:240},properties:{caching:"Signed URLs, cache keys, and regional origins"}},{id:"monitoring",type:"monitoring",componentId:"monitoring",label:"Media pipeline and delivery operations",description:"Tracks upload success, processing backlog, rendition failures, storage growth, CDN errors, playback startup, abuse, and deletion completion.",position:{x:1260,y:-80},properties:{alerts:"Backlog, processing quality, CDN, and lifecycle failures"}}],connections:[{id:"client-upload",source:"client",target:"upload",type:"http",label:"Upload or playback request",description:"Clients request a scoped upload URL, metadata change, processing status, or playback entitlement."},{id:"upload-object-store",source:"upload",target:"object-store",type:"data-flow",label:"Original media upload",description:"The client uploads directly to object storage using a short-lived signed URL; checksum and size are verified before acceptance."},{id:"upload-metadata",source:"upload",target:"metadata",type:"database-connection",label:"Media registration",description:"The gateway records owner, privacy, content type, checksum, and entitlement state before scheduling processing."},{id:"metadata-queue",source:"metadata",target:"queue",type:"message-queue",label:"Processing job",description:"A durable job describes the source object, requested renditions, policy version, and idempotency key."},{id:"queue-processor",source:"queue",target:"processor",type:"message-queue",label:"Transcode or moderation work",description:"Workers claim bounded jobs, retry transient failures, and isolate large or expensive media from interactive status reads."},{id:"processor-catalog",source:"processor",target:"catalog",type:"database-connection",label:"Verified rendition",description:"A rendition is published only after checksum, duration, codec, moderation, and completeness checks pass.",properties:{sourceHandle:"top",targetHandle:"bottom"}},{id:"catalog-cdn",source:"catalog",target:"cdn",type:"data-flow",label:"Signed playback manifest",description:"The CDN obtains an entitlement-scoped manifest and serves segments from the correct rendition origin."},{id:"cdn-client",source:"cdn",target:"client",type:"http",label:"Media playback or download",description:"Clients receive signed manifests or downloads with expiry and an explicit unavailable-rendition fallback.",properties:{sourceHandle:"bottom",targetHandle:"bottom"}},{id:"processor-monitoring",source:"processor",target:"monitoring",type:"data-flow",label:"Processing progress and quality",description:"Operations observes queue age, worker saturation, transcode failures, moderation outcomes, and completion time.",properties:{sourceHandle:"left-top",targetHandle:"right-bottom"}},{id:"cdn-monitoring",source:"cdn",target:"monitoring",type:"data-flow",label:"Playback and delivery telemetry",description:"Delivery metrics report startup latency, rebuffering, cache misses, signed URL failures, and regional errors.",properties:{sourceHandle:"top-left",targetHandle:"right-bottom"}}]},s=[{title:"Integrity and idempotent processing",points:["Use checksums and immutable source objects for global content delivery network deduplication and audit.","Derive output keys from asset, profile, and transform version so retries cannot corrupt a completed rendition.","Make completion callbacks and worker claims conditional on job version and attempt."]},{title:"Authorization at the edge",points:["Bind global content delivery network manifests and signed URLs to the viewer, entitlement version, and expiry.","Propagate takedown, privacy, and subscription changes to edge caches with bounded revocation delay.","Never let a cache hit bypass the policy decision for private or paid content."]},{title:"Cost, hot assets, and backpressure",points:["Separate interactive manifest latency from expensive global content delivery network processing and encode work.","Use queue priority, concurrency limits, and lifecycle policies for source and rendition storage.","Measure cache hit rate, startup latency, processing backlog, failed bytes, and egress cost by profile."]}],r=[{title:"Process on upload versus on demand",recommendation:"Precompute common global content delivery network profiles and generate rare profiles on demand with a durable job state.",caution:"Generating every possible profile up front wastes storage and processing budget."},{title:"Origin storage versus CDN caching",recommendation:"Keep the origin authoritative and use CDN caching for immutable or versioned outputs with explicit invalidation.",caution:"A cache cannot be the only copy of a global content delivery network rendition or the recovery path becomes undefined."},{title:"Quality versus delivery cost",recommendation:"Choose profiles from device, bandwidth, and business requirements, then measure quality and egress by cohort.",caution:"Maximal bitrate or resolution can make tail startup and cost unacceptable without improving viewing outcomes."}],c=["Letting global content delivery network processing run synchronously in the upload request.","Treating an upload-complete callback as trustworthy without checksum or size verification.","Using non-deterministic output paths so retries create duplicate or mismatched renditions.","Caching private or revoked content without an entitlement-aware invalidation plan.","Ignoring storage lifecycle, egress, queue backlog, and corrupt-input observability."],d=[{question:"How do you make global content delivery network processing retry-safe?",answer:"Use deterministic output identities, conditional job transitions, per-stage checkpoints, and a manifest that publishes only verified outputs."},{question:"What happens when an asset is deleted while processing?",answer:"Write a tombstone, cancel or quarantine pending work, revoke delivery, and let cleanup workers delete derived outputs idempotently."},{question:"How do you control media cost?",answer:"Track bytes by source, profile, cache, and region; apply lifecycle tiers and queue policies while preserving the outputs required by the product contract."}],l=[{criterion:"Requirements",description:"The answer addresses the global content delivery network workflow, scale, latency, durability, authorization, and failure contract."},{criterion:"Correctness",description:"The answer identifies the authoritative global content delivery network state, versioning or deduplication boundary, and how derived views converge."},{criterion:"Scale",description:"The answer partitions global content delivery network traffic, isolates hot keys, and moves fan-out, retries, or rebuilds behind bounded asynchronous work."},{criterion:"Operations",description:"The answer names freshness, backlog, error, cost, and recovery signals tied to the global content delivery network user experience."}],p={prompt:e,requirements:t,entities:o,apis:a,dataFlow:i,architecture:n,deepDives:s,tradeoffs:r,commonMistakes:c,followUps:d,rubric:l};export{a as apis,n as architecture,c as commonMistakes,i as dataFlow,s as deepDives,p as default,o as entities,d as followUps,e as prompt,t as requirements,l as rubric,r as tradeoffs};
